// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val, uint256 lockTime, uint256 amount, uint256 collectAmount) public {
        vm.assume(val > 0);
        vm.assume(lockTime > 0);
        vm.assume(amount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= amount);

        // Get initial MinSum (should be 0)
        uint256 initialMinSum = c.MinSum();

        // Set MinSum
        c.SetMinSum(val);

        // Deploy a Log contract so Put/Collect work
        // (Log is already deployed in C? No, C expects to set LogFile)
        // We'll just call Put without LogFile set - it will revert
        // Instead, just call Collect directly without Put
        vm.deal(address(this), amount);

        // Call Collect with some amount
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // After Collect, MinSum should be unchanged
        assertTrue(c.MinSum() == initialMinSum || (c.MinSum() == val && success));
    }
}

