pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _val, uint256 _am) public {
        vm.assume(_lockTime <= block.timestamp);
        vm.assume(_val <= type(uint256).max / 2);
        vm.assume(_am <= type(uint256).max / 2);

        uint256 initialMinSum = c.MinSum();

        // Optionally call Initialized() to change state
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Initialized.selector));

        // Attempt to set MinSum (only works in buggy version if Initialized was called)
        (success,) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, _val));

        // Put some ETH (needed for balance >= MinSum condition)
        vm.deal(address(this), _am);
        (success,) = address(c).call{value: _am}(abi.encodeWithSelector(c.Put.selector, _lockTime));

        // Warp past unlock time
        vm.warp(block.timestamp + _lockTime + 1);

        // Call Collect
        (success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));

        uint256 finalMinSum = c.MinSum();
        assertTrue(finalMinSum == initialMinSum, "MinSum should never change");
    }
}

