    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 _am) public {
        // Bound inputs to reasonable values
        _val = bound(_val, 0, 1e18);
        _lockTime = bound(_lockTime, 0, 365 days);
        _am = bound(_am, 0, 1e18);

        // Setup: call SetMinSum with a non-zero value so we can detect changes
        c.SetMinSum(1e18);
        vm.assume(address(c).balance >= _am); // Ensure contract has enough balance for Collect call
