pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, address _sender) public {
        // Bound _val to avoid overflow issues
        _val = bound(_val, 0, type(uint256).max);
        // Ensure _sender is not zero
        vm.assume(_sender != address(0));

        // Set MinSum to a known value
        c.SetMinSum(_val);
        uint256 expectedMinSum = _val;

        // Call Collect with arbitrary parameters (may revert, but we care about state after call)
        // Use prank to avoid issues with msg.sender
        vm.prank(_sender);
        // We call Collect with amount 0 and arbitrary balance; the call may revert if conditions not met
        // Use a try/catch so that the test continues even if Collect reverts
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, 0));
        // If success is false, the call reverted; still check MinSum
        // Assert that MinSum equals the expected value from SetMinSum
        assertTrue(c.MinSum() == expectedMinSum, "MinSum should be unchanged after Collect");
    }
}

