pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 lockTime, uint256 sendValue, uint256 withdrawAmount) public {
        // Ensure sendValue is at least 1 to make deposit meaningful
        vm.assume(sendValue > 0);
        // Bound withdrawAmount to avoid overflow in sub_uint256
        withdrawAmount = bound(withdrawAmount, 0, type(uint256).max);
        // Bound lockTime to a reasonable range
        lockTime = bound(lockTime, 0, 365 days);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(this));
        c.Initialized();

        // Record MinSum before
        uint256 minSumBefore = c.MinSum();

        // Fund caller and make a deposit
        vm.deal(caller, sendValue);
        vm.prank(caller);
        c.Put{value: sendValue}(lockTime);

        // Now call Collect; it may revert if conditions not met, but we only care about success
        // We need to ensure the call is likely to succeed: balance >= MinSum and enough time passed
        // Use vm.warp to satisfy the timestamp condition
        if (block.timestamp <= c.Acc(caller).unlockTime) {
            vm.warp(c.Acc(caller).unlockTime + 1);
        }
        // Ensure balance >= withdrawAmount (using sub_uint256 will revert if not, so we bound)
        if (c.Acc(caller).balance < withdrawAmount) {
            withdrawAmount = c.Acc(caller).balance;
        }
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdrawAmount));
        // Only assert if the call succeeded (revert would not change MinSum, but we want to test the bug)
        if (success) {
            // After Collect, MinSum must remain the same as before
            assertTrue(c.MinSum() == minSumBefore);
        }
    }
}

