        timeOffset = bound(timeOffset, 0, 365 days);

        // Set initial timestamp
        vm.warp(block.timestamp + 1);

        // Possibly call SetMinSum to set MinSum
        if (minSum > 0) {
            c.SetMinSum(minSum);
        }
        // Call Initialized to prevent further changes to MinSum/LogFile
        c.Initialized();
        // Fund the contract so that it can send ether
        vm.deal(address(c), 100 ether);
        // Fund msg.sender so they can send ether
        vm.deal(address(this), 100 ether);

        // Call Put to create a holder entry
        if (lockTime > 0) {
            c.Put{value: 0}(lockTime);
        }

        // Advance time to make withdrawal possible
        vm.warp(block.timestamp + lockTime + 1);

        // Attempt Collect
        uint256 minSumBefore = c.MinSum();
        // The reference P always has MinSum unchanged after Collect (no internal decrease)
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, amount));
        if (success) {
            // After successful Collect, MinSum must equal what was set before Initialized
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed after Collect");
        } else {
            // If revert, MinSum is also unchanged (the revert preserves state)
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed after reverted Collect");
        }
    }
}

